package localctl

// Only Docker's command boundary is controlled here. Genuine Docker/DB/media/
// browser observations live in tests/recovery-workspace, not in these tests.
import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"syscall"
	"testing"
)

func localFixture(t *testing.T, mode string) Controller {
	t.Helper()
	root := t.TempDir()
	dir := filepath.Join(root, "data/config")
	if e := os.MkdirAll(dir, 0700); e != nil {
		t.Fatal(e)
	}
	trace := filepath.Join(root, "trace")
	t.Setenv("TANGERINE_FAKE_TRACE", trace)
	t.Setenv("TANGERINE_FAKE_MODE", mode)
	script := `#!/bin/sh
printf '%s\n' "$*" >> "$TANGERINE_FAKE_TRACE"
case "$*" in
 *'volume inspect'*) [ "$TANGERINE_FAKE_MODE" = existing-volume ] && exit 0; exit 1;;
 *'ps --status running --services'*) printf 'web\napi\nspeech\n';;
 *'stop web api speech'*) [ "$TANGERINE_FAKE_MODE" = partial-stop ] || [ "$TANGERINE_FAKE_MODE" = partial-stop-restart-failure ] && exit 1;;
 *'snapshot-create'*) printf 'literal native archive bytes';;
 *'start web api speech'*) [ "$TANGERINE_FAKE_MODE" = restart-failure ] || [ "$TANGERINE_FAKE_MODE" = partial-stop-restart-failure ] && exit 1;;
 *'up -d --wait'*) [ "$TANGERINE_FAKE_MODE" = target-failure ] && exit 1;;
esac
exit 0
`
	if e := os.WriteFile(filepath.Join(root, "docker"), []byte(script), 0700); e != nil {
		t.Fatal(e)
	}
	t.Setenv("PATH", root+":"+os.Getenv("PATH"))
	return Controller{Root: root, Project: "original", Runtime: filepath.Join(dir, "runtime.env")}
}
func targetFixture(t *testing.T, c Controller) {
	t.Helper()
	dir := filepath.Join(c.Root, "data/config/restores/restored")
	if e := os.MkdirAll(dir, 0700); e != nil {
		t.Fatal(e)
	}
	for k, v := range map[string]string{"status": "ready\n", "runtime.env": "private-test-credentials"} {
		if e := os.WriteFile(filepath.Join(dir, k), []byte(v), 0600); e != nil {
			t.Fatal(e)
		}
	}
}
func TestLocalRecoveryBackupPositive(t *testing.T) {
	c := localFixture(t, "good")
	p, e := c.Backup(context.Background(), "saved.tar.gz")
	if e != nil {
		t.Fatal(e)
	}
	b, e := os.ReadFile(filepath.Join(c.Root, "data/backups/saved.tar.gz"))
	if e != nil || string(b) != "literal native archive bytes" || p["status"] != "complete" {
		t.Fatal(p, e)
	}
	trace, _ := os.ReadFile(filepath.Join(c.Root, "trace"))
	if !strings.Contains(string(trace), "stop web api speech") || !strings.Contains(string(trace), "start web api speech") {
		t.Fatal(string(trace))
	}
}
func TestLocalRecoveryBackupRestartNegative(t *testing.T) {
	c := localFixture(t, "restart-failure")
	_, e := c.Backup(context.Background(), "saved.tar.gz")
	if e == nil || !strings.Contains(e.Error(), "BACKUP_SAVED_RESTART_REQUIRED") {
		t.Fatal(e)
	}
	if _, e = os.Stat(filepath.Join(c.Root, "data/backups/saved.tar.gz")); e != nil {
		t.Fatal("saved backup lost", e)
	}
}
func TestLocalRecoveryBackupCollisionNegative(t *testing.T) {
	c := localFixture(t, "good")
	_, e := c.Backup(context.Background(), "saved.tar.gz")
	if e != nil {
		t.Fatal(e)
	}
	_, e = c.Backup(context.Background(), "saved.tar.gz")
	if e == nil || !strings.Contains(e.Error(), "BACKUP_EXISTS") {
		t.Fatal(e)
	}
}
func TestLocalRecoveryExplicitSwitchPositive(t *testing.T) {
	c := localFixture(t, "good")
	targetFixture(t, c)
	p, e := c.Switch(context.Background(), "restored")
	if e != nil {
		t.Fatal(e)
	}
	b, _ := os.ReadFile(filepath.Join(c.Root, "data/config/active-project"))
	if string(b) != "restored\n" || p["previous_volumes"] != "retained" {
		t.Fatal(p, string(b))
	}
}
func TestLocalRecoverySwitchRollbackNegative(t *testing.T) {
	for _, mode := range []string{"target-failure", "marker-failure"} {
		t.Run(mode, func(t *testing.T) {
			c := localFixture(t, mode)
			targetFixture(t, c)
			if mode == "marker-failure" {
				if e := os.Mkdir(filepath.Join(c.Root, "data/config/active-project"), 0700); e != nil {
					t.Fatal(e)
				}
			}
			if _, e := c.Switch(context.Background(), "restored"); e == nil {
				t.Fatal("failed target selected")
			}
			trace, _ := os.ReadFile(filepath.Join(c.Root, "trace"))
			if !strings.Contains(string(trace), "stop web api speech") || !strings.Contains(string(trace), "start web api speech") {
				t.Fatal("previous workspace was not recovered", string(trace))
			}
		})
	}
}
func TestLocalRecoveryExistingVolumeNegative(t *testing.T) {
	c := localFixture(t, "existing-volume")
	_, e := c.Restore(context.Background(), "missing.tar.gz", "restored")
	if e == nil || !strings.Contains(e.Error(), "RESTORE_TARGET_EXISTS") {
		t.Fatal(e)
	}
}
func TestLocalRecoveryBusyNegative(t *testing.T) {
	c := localFixture(t, "good")
	f, e := os.OpenFile(filepath.Join(c.Root, "data/config/.maintenance-lock"), os.O_CREATE|os.O_RDWR, 0600)
	if e != nil {
		t.Fatal(e)
	}
	defer f.Close()
	if e = syscall.Flock(int(f.Fd()), syscall.LOCK_EX); e != nil {
		t.Fatal(e)
	}
	e = Command(context.Background(), c.Root, c.Project, c.Runtime, []string{"backup", "test.tar.gz"}, os.Stdout)
	if e == nil || !strings.Contains(e.Error(), "WORKSPACE_BUSY") {
		t.Fatal(e)
	}
}
func TestLocalRecoveryPurgePositive(t *testing.T) {
	c := localFixture(t, "good")
	t.Setenv("CONFIRM_DELETE_LOCAL_LAB", "yes")
	dir := filepath.Join(c.Root, "data/config/lab-native")
	if e := os.Mkdir(dir, 0700); e != nil {
		t.Fatal(e)
	}
	if e := os.WriteFile(filepath.Join(dir, "copied-body"), []byte("constructed private body"), 0600); e != nil {
		t.Fatal(e)
	}
	_, e := c.PurgeLab(context.Background())
	if e != nil {
		t.Fatal(e)
	}
	if _, e = os.Stat(dir); !os.IsNotExist(e) {
		t.Fatal("copied body remains", e)
	}
}
func TestLocalRecoveryPurgeConfirmationNegative(t *testing.T) {
	c := localFixture(t, "good")
	t.Setenv("CONFIRM_DELETE_LOCAL_LAB", "")
	if _, e := c.PurgeLab(context.Background()); e == nil {
		t.Fatal("unconfirmed erasure")
	}
	if _, e := os.Stat(filepath.Join(c.Root, "trace")); !os.IsNotExist(e) {
		t.Fatal("unconfirmed command reached Docker")
	}
}

func TestLocalRecoveryPartialStopNegative(t *testing.T) {
	for _, action := range []string{"backup", "switch"} {
		t.Run(action, func(t *testing.T) {
			c := localFixture(t, "partial-stop")
			targetFixture(t, c)
			var e error
			if action == "backup" {
				_, e = c.Backup(context.Background(), "saved.tar.gz")
			} else {
				_, e = c.Switch(context.Background(), "restored")
			}
			if e == nil {
				t.Fatal("partial stop accepted")
			}
			trace, _ := os.ReadFile(filepath.Join(c.Root, "trace"))
			if !strings.Contains(string(trace), "start web api speech") {
				t.Fatal("partially stopped workspace was not recovered", string(trace))
			}
			if strings.Contains(string(trace), "snapshot-create") || strings.Contains(string(trace), "up -d --wait") {
				t.Fatal("continued after failed stop", string(trace))
			}
			if _, e = os.Stat(filepath.Join(c.Root, "data/backups/saved.tar.gz")); !os.IsNotExist(e) {
				t.Fatal("published incomplete backup", e)
			}
			if _, e = os.Stat(filepath.Join(c.Root, "data/config/active-project")); !os.IsNotExist(e) {
				t.Fatal("selected failed workspace", e)
			}
		})
	}
}

func TestLocalRecoveryRecoveryFailureNegative(t *testing.T) {
	for _, action := range []string{"backup", "switch"} {
		t.Run(action, func(t *testing.T) {
			c := localFixture(t, "partial-stop-restart-failure")
			targetFixture(t, c)
			var e error
			if action == "backup" {
				_, e = c.Backup(context.Background(), "saved.tar.gz")
			} else {
				_, e = c.Switch(context.Background(), "restored")
			}
			if e == nil || !strings.Contains(e.Error(), "WORKSPACE_RECOVERY_REQUIRED") {
				t.Fatal("failed restart was misreported", e)
			}
			if _, e = os.Stat(filepath.Join(c.Root, "data/config/active-project")); !os.IsNotExist(e) {
				t.Fatal("failed selection published", e)
			}
		})
	}
}

services/api/internal/recovery/archive_t.fixture_source:
package recovery

import (
	"archive/tar"
	"bytes"
	"compress/gzip"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func archiveFixture(t *testing.T) []byte {
	t.Helper()
	var b bytes.Buffer
	w := New(&b, "literal-backup", []string{"001.sql", "002.sql"})
	for name, body := range map[string]string{"database.dump": "literal database bytes", "media/frozen-audio": "\x00\x01\xffexact audio", "models/voices/voice.bin": "installed voice", "lab/mlflow.db": "constructed SQLite transport bytes"} {
		if e := w.Add(name, int64(len(body)), strings.NewReader(body)); e != nil {
			t.Fatal(e)
		}
	}
	w.Manifest.Models = true
	w.Manifest.Lab = true
	if e := w.Close(); e != nil {
		t.Fatal(e)
	}
	return b.Bytes()
}
func TestRecoveryArchivePositive(t *testing.T) {
	dir := t.TempDir()
	m, e := Admit(bytes.NewReader(archiveFixture(t)), dir, []string{"001.sql", "002.sql", "003.sql"})
	if e != nil {
		t.Fatal(e)
	}
	if m.ID != "literal-backup" || len(m.Files) != 4 || m.Secrets || !m.Models || !m.Lab {
		t.Fatal(m)
	}
	b, e := os.ReadFile(filepath.Join(dir, "media/frozen-audio"))
	if e != nil || string(b) != "\x00\x01\xffexact audio" {
		t.Fatal(string(b), e)
	}
}
func TestRecoveryOlderSchemaPositive(t *testing.T) {
	_, e := Admit(bytes.NewReader(archiveFixture(t)), t.TempDir(), []string{"001.sql", "002.sql", "003.sql"})
	if e != nil {
		t.Fatal(e)
	}
}
func badArchive(t *testing.T, name string, kind byte, manifest bool) []byte {
	t.Helper()
	var b bytes.Buffer
	g := gzip.NewWriter(&b)
	w := tar.NewWriter(g)
	_ = w.WriteHeader(&tar.Header{Name: name, Typeflag: kind, Mode: 0600, Size: 1, Linkname: "/outside"})
	_, _ = w.Write([]byte("x"))
	if manifest {
		raw, _ := json.Marshal(Manifest{Format: 2, ID: "bad", Migrations: []string{"001.sql"}, Files: []File{{Path: name, SHA: strings.Repeat("0", 64), Bytes: 1}}})
		_ = w.WriteHeader(&tar.Header{Name: "manifest.json", Typeflag: tar.TypeReg, Mode: 0600, Size: int64(len(raw))})
		_, _ = w.Write(raw)
	}
	_ = w.Close()
	_ = g.Close()
	return b.Bytes()
}
func TestRecoveryUnsafePathNegative(t *testing.T) {
	for _, name := range []string{"../outside", "/outside", "media/../../outside", "models\\outside", "credentials/private.key"} {
		t.Run(strings.ReplaceAll(name, "/", "_"), func(t *testing.T) {
			if _, e := Admit(bytes.NewReader(badArchive(t, name, tar.TypeReg, true)), t.TempDir(), []string{"001.sql"}); e == nil {
				t.Fatal("unsafe archive admitted", name)
			}
		})
	}
}
func TestRecoveryLinkNegative(t *testing.T) {
	if _, e := Admit(bytes.NewReader(badArchive(t, "media/link", tar.TypeSymlink, false)), t.TempDir(), []string{"001.sql"}); e == nil {
		t.Fatal("link admitted")
	}
}
func TestRecoveryTamperNegative(t *testing.T) {
	if _, e := Admit(bytes.NewReader(badArchive(t, "database.dump", tar.TypeReg, true)), t.TempDir(), []string{"001.sql"}); e == nil || !strings.Contains(e.Error(), "hash") {
		t.Fatal(e)
	}
}
func TestRecoveryFutureSchemaNegative(t *testing.T) {
	if _, e := Admit(bytes.NewReader(archiveFixture(t)), t.TempDir(), []string{"001.sql"}); e == nil || !strings.Contains(e.Error(), "INCOMPATIBLE") {
		t.Fatal(e)
	}
}
func TestRecoveryIncompleteNegative(t *testing.T) {
	data := archiveFixture(t)
	for _, n := range []int{0, len(data) / 2, len(data) - 5} {
		if _, e := Admit(bytes.NewReader(data[:n]), t.TempDir(), []string{"001.sql", "002.sql"}); e == nil {
			t.Fatal("truncated archive admitted", n)
		}
	}
}
func TestRecoveryDuplicateNegative(t *testing.T) {
	var b bytes.Buffer
	w := New(&b, "duplicate", []string{"001.sql"})
	if e := w.Add("database.dump", 1, strings.NewReader("x")); e != nil {
		t.Fatal(e)
	}
	if e := w.Add("database.dump", 1, strings.NewReader("y")); e == nil {
		t.Fatal("duplicate overwritten")
	}
}
func TestRecoveryDestinationNegative(t *testing.T) {
	dir := t.TempDir()
	if e := os.WriteFile(filepath.Join(dir, "database.dump"), []byte("previous"), 0600); e != nil {
		t.Fatal(e)
	}
	if _, e := Admit(bytes.NewReader(archiveFixture(t)), dir, []string{"001.sql", "002.sql"}); e == nil {
		t.Fatal("existing file replaced")
	}
	b, _ := os.ReadFile(filepath.Join(dir, "database.dump"))
	if string(b) != "previous" {
		t.Fatal(string(b))
	}
}

tests/native_recovery_test.go.fixture_source:
package app

// Constructed model/speech responses drive the genuine foreground owners; these
// tests do not establish model quality, accents or a hosted billing entitlement.
import (
	"context"
	"encoding/json"
	"github.com/google/uuid"
	"github.com/minio/minio-go/v7"
	"io"
	"net/http"
	"net/http/httptest"
	"net/http/httputil"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"sync/atomic"
	"testing"
)

func recoveryHTTP(t *testing.T, s *Server, path, key string, body any) *httptest.ResponseRecorder {
	t.Helper()
	r := httptest.NewRequest(http.MethodPost, path, strings.NewReader(string(mustJSON(body))))
	r.Header.Set("Authorization", "Bearer "+s.token)
	r.Header.Set("Origin", s.Origin)
	r.Header.Set("Content-Type", "application/json")
	r.Header.Set("Idempotency-Key", key)
	w := httptest.NewRecorder()
	s.Handler().ServeHTTP(w, r)
	return w
}
func recoveryRequest(t *testing.T, s *Server) CanonicalPreparationRequest {
	t.Helper()
	b, e := s.Store.WriteBlueprint(context.Background(), mustJSON(map[string]any{"exercise_request": qualityGenerationRequest()}), uuid.NewString())
	requireListening(t, e)
	c, _, e := s.Store.Configuration(context.Background())
	requireListening(t, e)
	return CanonicalPreparationRequest{BlueprintID: b["id"].(string), ConfigurationSHA: c["configuration_sha256"].(string), Sources: []string{}, Attempt: 1}
}
func TestNativeRecoveryGeneratePositive(t *testing.T) {
	s, calls := qualityGenerationServer(t, false)
	s.token = "recovery-token"
	speech := qualitySpeechTarget(t, s, false)
	key := uuid.NewString()
	request := recoveryRequest(t, s)
	w := recoveryHTTP(t, s, "/api/v1/candidates:generate", key, request)
	if w.Code != 200 || calls.Load() != 2 || speech.Load() != 1 {
		t.Fatal(w.Code, w.Body.String(), calls.Load(), speech.Load())
	}
	var p map[string]any
	requireListening(t, json.Unmarshal(w.Body.Bytes(), &p))
	if p["audio_available"] != true || p["settings_asset_id"] != nil || p["key_id"] != nil {
		t.Fatal(p)
	}
	w = recoveryHTTP(t, s, "/api/v1/candidates:generate", key, request)
	if w.Code != 200 || calls.Load() != 2 || speech.Load() != 1 {
		t.Fatal("replay dispatched", w.Code, w.Body.String(), calls.Load(), speech.Load())
	}
	saveRecoveryControl(t, s)
}
func TestNativeRecoveryResumePositive(t *testing.T) {
	s, calls := qualityGenerationServer(t, false)
	s.token = "recovery-token"
	failed := qualitySpeechTarget(t, s, true)
	w := recoveryHTTP(t, s, "/api/v1/candidates:generate", uuid.NewString(), recoveryRequest(t, s))
	if w.Code == 200 || calls.Load() != 2 || failed.Load() != 1 {
		t.Fatal(w.Code, w.Body.String(), calls.Load(), failed.Load())
	}
	var response map[string]any
	requireListening(t, json.Unmarshal(w.Body.Bytes(), &response))
	p := response["preparation"].(map[string]any)
	id := p["id"].(string)
	c, rev, e := s.Store.Configuration(context.Background())
	requireListening(t, e)
	c["speech_profile"] = "azure-standard-en-v1"
	for _, k := range []string{"workspace_id", "configuration_sha256", "provider_access_policy"} {
		delete(c, k)
	}
	_, _, e = s.Store.PutConfiguration(context.Background(), mustJSON(c), uuid.NewString(), rev)
	requireListening(t, e)
	speech := qualitySpeechTarget(t, s, false)
	resumeKey := uuid.NewString()
	w = recoveryHTTP(t, s, "/api/v1/preparations/"+id+":resume", resumeKey, map[string]any{})
	if w.Code != 200 || calls.Load() != 2 || speech.Load() != 1 {
		t.Fatal(w.Code, w.Body.String(), calls.Load(), speech.Load())
	}
	firstResult := w.Body.String()
	w = recoveryHTTP(t, s, "/api/v1/preparations/"+id+":resume", resumeKey, map[string]any{})
	if w.Code != 200 || w.Body.String() != firstResult || calls.Load() != 2 || speech.Load() != 1 {
		t.Fatal("Resume replay changed the action", w.Code, w.Body.String(), firstResult)
	}

	saved, e := s.Store.Preparation(context.Background(), id)
	requireListening(t, e)
	if saved["selected_speech_profile"] != "kokoro-local-en-v1" {
		t.Fatal("settings replaced", saved)
	}
	rows, e := s.Store.Preparations(context.Background(), 50, "")
	requireListening(t, e)
	if len(rows["items"].([]map[string]any)) != 1 || calls.Load() != 2 {
		t.Fatal("readback called provider")
	}
}
func TestNativeRecoveryUnknownNegative(t *testing.T) {
	s, calls := qualityGenerationServer(t, false)
	s.token = "recovery-token"
	w := recoveryHTTP(t, s, "/api/v1/preparations/"+uuid.NewString()+":resume", uuid.NewString(), map[string]any{})
	if w.Code != 404 || calls.Load() != 0 {
		t.Fatal(w.Code, w.Body.String(), calls.Load())
	}
}
func TestNativeRecoveryMalformedNegative(t *testing.T) {
	s, calls := qualityGenerationServer(t, false)
	s.token = "recovery-token"
	for _, body := range []any{map[string]any{}, map[string]any{"generation_attempt": -1}} {
		w := recoveryHTTP(t, s, "/api/v1/candidates:generate", uuid.NewString(), body)
		if w.Code == 200 || calls.Load() != 0 {
			t.Fatal(w.Code, calls.Load())
		}
	}
}
func TestNativeRecoveryMutationFailureNegative(t *testing.T) {
	s, calls := qualityGenerationServer(t, true)
	s.token = "recovery-token"
	speech := qualitySpeechTarget(t, s, false)
	w := recoveryHTTP(t, s, "/api/v1/candidates:generate", uuid.NewString(), recoveryRequest(t, s))
	if w.Code == 200 || calls.Load() != 3 || speech.Load() != 0 {
		t.Fatal(w.Code, w.Body.String(), calls.Load(), speech.Load())
	}
	rows, e := s.Store.Preparations(context.Background(), 50, "")
	requireListening(t, e)
	p := rows["items"].([]map[string]any)[0]
	if p["phase_states"].(map[string]any)["canonical_text"] != "complete" || p["canonical_asset_id"] == nil {
		t.Fatal("source lost", p)
	}
}

func TestNativeRecoveryDeletionPositive(t *testing.T) {
	f := listeningCase(t)
	id := f.start(t)
	plan, e := f.s.Store.PlanDeletion(context.Background(), DeletionSelection{IDs: []string{id}})
	requireListening(t, e)
	if len(plan.Documents) == 0 || len(plan.Blocked) != 0 {
		t.Fatal(plan)
	}
	result, e := f.s.Store.ApplyDeletion(context.Background(), plan.ID, plan.Digest)
	requireListening(t, e)
	if result.State != "erased" {
		t.Fatal(result)
	}
	var n int
	requireListening(t, f.s.Store.DB.QueryRow(context.Background(), "SELECT count(*) FROM entity_head WHERE id=$1", id).Scan(&n))
	if n != 0 {
		t.Fatal("attempt remains")
	}
	_, e = f.s.Store.ReadAsset(context.Background(), recoveryAudioID(t, f))
	requireListening(t, e)
}
func TestNativeRecoveryDeletionConfirmationNegative(t *testing.T) {
	f := listeningCase(t)
	id := f.start(t)
	p, e := f.s.Store.PlanDeletion(context.Background(), DeletionSelection{IDs: []string{id}})
	requireListening(t, e)
	if _, e = f.s.Store.ApplyDeletion(context.Background(), p.ID, strings.Repeat("0", 64)); e == nil {
		t.Fatal("wrong confirmation admitted")
	}
	var n int
	requireListening(t, f.s.Store.DB.QueryRow(context.Background(), "SELECT count(*) FROM entity_head WHERE id=$1", id).Scan(&n))
	if n != 1 {
		t.Fatal("unconfirmed erasure")
	}
}
func TestNativeRecoveryReferencedMediaNegative(t *testing.T) {
	f := listeningCase(t)
	p, e := f.s.Store.PlanDeletion(context.Background(), DeletionSelection{IDs: []string{recoveryAudioID(t, f)}})
	requireListening(t, e)
	if len(p.Blocked) == 0 {
		t.Fatal("referenced audio not blocked", p)
	}
	if _, e = f.s.Store.ApplyDeletion(context.Background(), p.ID, p.Digest); e == nil {
		t.Fatal("referenced audio removed")
	}
}
func TestNativeRecoveryCleanupPreviewPositive(t *testing.T) {
	s := listeningNative(t)
	p, e := s.PlanDeletion(context.Background(), DeletionSelection{Orphans: true})
	requireListening(t, e)
	if p.State != "preview" || len(p.Documents) != 0 || len(p.Assets) != 0 {
		t.Fatal(p)
	}
}

func recoveryAudioID(t *testing.T, f listeningFixture) string {
	t.Helper()
	var id string
	requireListening(t, f.s.Store.DB.QueryRow(context.Background(), "SELECT audio_asset_id FROM listening_case WHERE case_version_id=$1", f.id).Scan(&id))
	return id
}
func TestNativeRecoveryScoredDeletionPositive(t *testing.T) {
	f := scoringFixture(t, false)
	_, e := f.interpret(t, uuid.NewString())
