	state, e := f.interpret(t, uuid.NewString())
	if e == nil || state.Extraction == nil || state.Mapping != nil {
		t.Fatal(state, e)
	}
	old := *state.Extraction
	f.mode.Store("good")
	next, e := f.interpret(t, uuid.NewString())
	requireListening(t, e)
