func TestNativeInterpretationConcurrentNegative(t *testing.T) {
	f := interpretationNative(t, "blocked")
	t.Cleanup(func() {
		select {
		case <-f.release:
		default:
			close(f.release)
		}
	})
	result := make(chan error, 1)
	go func() { _, e := f.interpret(t, uuid.NewString()); result <- e }()
	select {
